This version avoids building a parent map. First, it saves the path from the root to the target. The target subtree is searched downward, then every ancestor on the saved path is checked. From an ancestor, only the subtree not containing the target is searched.

For example, if the target is two edges below an ancestor, that ancestor is added when `k` is 2. Its other child subtree must be searched at distance `k - 3`.

```java
import java.util.*;

class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> answer = new ArrayList<>();
        if (root == null || target == null || k < 0) {
            return answer;
        }

        List<TreeNode> path = new ArrayList<>();
        if (!findPath(root, target, path)) {
            return answer;
        }

        collectDown(target, k, null, answer);

        for (int i = path.size() - 2; i >= 0; --i) {
            int distanceUp = path.size() - 1 - i;

            if (distanceUp == k) {
                answer.add(path.get(i).data);
            }

            int remaining = k - distanceUp - 1;
            if (remaining >= 0) {
                TreeNode ancestor = path.get(i);
                TreeNode childOnTargetPath = path.get(i + 1);
                TreeNode otherSubtree;

                if (ancestor.left == childOnTargetPath) {
                    otherSubtree = ancestor.right;
                } else {
                    otherSubtree = ancestor.left;
                }

                collectDown(otherSubtree, remaining, null, answer);
            }
        }

        return answer;
    }

    private boolean findPath(TreeNode node, TreeNode target, List<TreeNode> path) {
        if (node == null) {
            return false;
        }

        path.add(node);
        if (node == target) {
            return true;
        }

        if (findPath(node.left, target, path) || findPath(node.right, target, path)) {
            return true;
        }

        path.remove(path.size() - 1);
        return false;
    }

    private void collectDown(TreeNode node, int distance, TreeNode blocked,
                             List<Integer> answer) {
        if (node == null || node == blocked || distance < 0) {
            return;
        }

        if (distance == 0) {
            answer.add(node.data);
            return;
        }

        collectDown(node.left, distance - 1, blocked, answer);
        collectDown(node.right, distance - 1, blocked, answer);
    }
}
```

The input tree is not changed. Both the path search and the downward searches together take `O(n)` time in the worst case. Extra space is `O(h)` for recursion and the root-to-target path, where `h` is the tree height.

The tree does not have parent pointers, so the first BFS records the parent of every node. A second BFS starts at `target` and treats the tree like an undirected graph. Each level is one more edge away.

The visited set is important because a node can be reached from its child and its parent. This also handles `k == 0`, where the target itself is returned.

```cpp
class Solution {
public:
    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        vector<int> answer;
        if (root == nullptr || target == nullptr || k < 0) {
            return answer;
        }

        unordered_map<TreeNode*, TreeNode*> parent;
        queue<TreeNode*> buildQueue;
        buildQueue.push(root);

        while (!buildQueue.empty()) {
            TreeNode* node = buildQueue.front();
            buildQueue.pop();

            if (node->left != nullptr) {
                parent[node->left] = node;
                buildQueue.push(node->left);
            }
            if (node->right != nullptr) {
                parent[node->right] = node;
                buildQueue.push(node->right);
            }
        }

        queue<TreeNode*> searchQueue;
        unordered_set<TreeNode*> visited;
        searchQueue.push(target);
        visited.insert(target);

        int distance = 0;
        while (!searchQueue.empty() && distance < k) {
            int levelSize = static_cast<int>(searchQueue.size());

            for (int i = 0; i < levelSize; ++i) {
                TreeNode* node = searchQueue.front();
                searchQueue.pop();

                if (node->left != nullptr && visited.insert(node->left).second) {
                    searchQueue.push(node->left);
                }
                if (node->right != nullptr && visited.insert(node->right).second) {
                    searchQueue.push(node->right);
                }

                auto parentIt = parent.find(node);
                if (parentIt != parent.end() && visited.insert(parentIt->second).second) {
                    searchQueue.push(parentIt->second);
                }
            }
            ++distance;
        }

        while (!searchQueue.empty()) {
            answer.push_back(searchQueue.front()->data);
            searchQueue.pop();
        }
        return answer;
    }
};
```

Time complexity: `O(n)`.
Space complexity: `O(n)` for the parent map, visited set, and queues.

A binary tree only gives child links, but distance can also go through a parent. This code builds a small undirected graph using the actual node objects as keys. Then normal BFS gives the answer level by level.

Dry run for a target with `k = 2`: the first queue contains the target, the next queue contains all nodes one edge away, and the following queue contains the result nodes. BFS stops before expanding that final queue.

```python
from collections import defaultdict, deque

class Solution:
    def distanceK(self, root, target, k):
        if root is None or target is None or k < 0:
            return []

        graph = defaultdict(list)

        def build_graph(node):
            if node is None:
                return

            if node.left is not None:
                graph[node].append(node.left)
                graph[node.left].append(node)
                build_graph(node.left)

            if node.right is not None:
                graph[node].append(node.right)
                graph[node.right].append(node)
                build_graph(node.right)

        build_graph(root)

        queue = deque([target])
        visited = {target}
        distance = 0

        while queue and distance < k:
            for _ in range(len(queue)):
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            distance += 1

        return [node.data for node in queue]
```

Important edge cases are already covered: an empty tree returns an empty list, and `k == 0` leaves only the target in the queue.

Time complexity: `O(n)`.
Space complexity: `O(n)` for the graph, visited set, and BFS queue.

This keeps the parent map and the distance search separate. Once every child has a parent entry, the BFS can move left, right, or upward. Nodes are marked when they enter the queue, so the same node cannot be added twice.

Dry run with target `5` and distance `2`: level zero is `[5]`, level one contains its children and parent, and level two contains the nodes returned by the method. If no nodes exist at a requested distance, the queue becomes empty and the result is simply empty.

```java
import java.util.*;

class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> answer = new ArrayList<>();
        if (root == null || target == null || k < 0) {
            return answer;
        }

        Map<TreeNode, TreeNode> parent = new HashMap<>();
        Queue<TreeNode> buildQueue = new ArrayDeque<>();
        buildQueue.offer(root);

        while (!buildQueue.isEmpty()) {
            TreeNode node = buildQueue.poll();

            if (node.left != null) {
                parent.put(node.left, node);
                buildQueue.offer(node.left);
            }
            if (node.right != null) {
                parent.put(node.right, node);
                buildQueue.offer(node.right);
            }
        }

        Queue<TreeNode> queue = new ArrayDeque<>();
        Set<TreeNode> visited = new HashSet<>();
        queue.offer(target);
        visited.add(target);

        int distance = 0;
        while (!queue.isEmpty() && distance < k) {
            int levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && visited.add(node.left)) {
                    queue.offer(node.left);
                }
                if (node.right != null && visited.add(node.right)) {
                    queue.offer(node.right);
                }

                TreeNode parentNode = parent.get(node);
                if (parentNode != null && visited.add(parentNode)) {
                    queue.offer(parentNode);
                }
            }
            distance++;
        }

        while (!queue.isEmpty()) {
            answer.add(queue.poll().data);
        }
        return answer;
    }
}
```

Time complexity: `O(n)`, since each tree node is processed at most a few times. Space complexity: `O(n)` for the parent map, visited set, and queues.

Here the root-to-target path does most of the work. After finding that path, the code checks three kinds of nodes: descendants of the target, ancestors of the target, and nodes in the sibling subtrees of those ancestors.

The `blocked` argument stops a search from entering the branch that leads back to the target. That prevents duplicates without changing the input tree.

```cpp
class Solution {
public:
    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        vector<int> answer;
        if (root == nullptr || target == nullptr || k < 0) {
            return answer;
        }

        vector<TreeNode*> path;
        if (!findPath(root, target, path)) {
            return answer;
        }

        collectDown(target, k, nullptr, answer);

        for (int index = static_cast<int>(path.size()) - 2; index >= 0; --index) {
            int distanceFromTarget = static_cast<int>(path.size()) - 1 - index;
            TreeNode* ancestor = path[index];

            if (distanceFromTarget == k) {
                answer.push_back(ancestor->data);
            }

            int downDistance = k - distanceFromTarget - 1;
            if (downDistance < 0) {
                continue;
            }

            TreeNode* pathChild = path[index + 1];
            TreeNode* otherChild = (ancestor->left == pathChild)
                ? ancestor->right
                : ancestor->left;

            collectDown(otherChild, downDistance, nullptr, answer);
        }

        return answer;
    }

private:
    bool findPath(TreeNode* node, TreeNode* target, vector<TreeNode*>& path) {
        if (node == nullptr) {
            return false;
        }

        path.push_back(node);
        if (node == target) {
            return true;
        }

        if (findPath(node->left, target, path) ||
            findPath(node->right, target, path)) {
            return true;
        }

        path.pop_back();
        return false;
    }

    void collectDown(TreeNode* node, int distance, TreeNode* blocked,
                     vector<int>& answer) {
        if (node == nullptr || node == blocked || distance < 0) {
            return;
        }

        if (distance == 0) {
            answer.push_back(node->data);
            return;
        }

        collectDown(node->left, distance - 1, blocked, answer);
        collectDown(node->right, distance - 1, blocked, answer);
    }
};
```

If `k` is larger than every possible path, no branch reaches distance zero, so the returned vector stays empty. A single-node tree also works, returning that node only when `k` is zero.

Time complexity: `O(n)` in the worst case. Space complexity: `O(h)` for the path and recursive calls, not counting the returned values.

